@startuml

class Provider {
  + Name : string
  + Location : string
}

class Cruise {
  + Number : int
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Employee {
  + Name : string
  + Ssn : int
}

class Guest {
  + Name : string
  + IsVIP : boolean
}

class Ship {
  + Name : string
  + Decks : int
  + Length : float
  + PassengerCount : int
}

class TravelAgency {
  + Name : string
  + Address : string
}

class DestinationArea {
  + Name : string
  + SeaName : string
}

class Show {
  + Title : string
  + Duration : int
}

class Ticket {
  + BookingNumber : string
  + BookingDate : date
}

Provider "1" -- "*" Cruise
Cruise "*" -- "1..*" Employee
Cruise "*" -- "*" Guest
Cruise "*" -- "1" Ship
Cruise "*" -- "1" DestinationArea
Cruise "1" -- "*" Show
Cruise "1" -- "*" Ticket
Guest "1" -- "*" Ticket
TravelAgency "1" -- "*" Cruise : books
Ticket "*" -- "1" Cruise

@enduml

